# How data/ex1_92_glue_sst2_layer20.npz was built. Needs the authors’ SAE-Probes repo and data; you do not need to run it.
# The same code as on the workshop page. Run from the repo root: see tools/build_ex1_file.py
# Do not edit this file; copy it into work/ to change it.

import numpy as np, pandas as pd, torch
from transformer_lens import HookedTransformer
# from the authors' SAE-Probes repository
from utils_data import get_train_test_indices
torch.set_grad_enabled(False)
# fp32, as in the paper
model = HookedTransformer.from_pretrained("google/gemma-2-9b",
                                          device="cuda")
tok = model.tokenizer; tok.truncation_side = "left"

# from the authors' dataset download
df = pd.read_csv("cleaned_data/92_glue_sst2.csv")[:5000]
X = []
for p in df.prompt:
    ids = tok(p, truncation=True, max_length=1024,
              return_tensors="pt")["input_ids"].cuda()
    _, c = model.run_with_cache(
        ids,
        names_filter="blocks.20.hook_resid_post",
        stop_at_layer=21)
    # last token, layer 20
    X.append(c["blocks.20.hook_resid_post"][0, -1]
             .float().cpu().numpy())
y = pd.factorize(df.target, sort=True)[0]
# the authors' split
tr, te = get_train_test_indices(y, 1024, len(y) - 1025, 0.5, 42)
np.savez_compressed("ex1_92_glue_sst2_layer20.npz",
                    X=np.array(X, np.float16), y=y,
                    train_idx=np.array(tr), test_idx=np.array(te),
                    prompts=np.array(df.prompt))
